function buildRaw(to, subject, html) {
  const mime = [
    'From: Hector Meza <h.mezarealty@gmail.com>',
    `To: ${to}`,
    'Reply-To: hmeza@briggsfreeman.com',
    `Subject: ${subject}`,
    'MIME-Version: 1.0',
    'Content-Type: text/html; charset=UTF-8',
    '',
    html
  ].join('\r\n');
  return Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
const raw = $input.first().json;
const link = 'https://g.page/r/CabJGOEHci6qEBM/review';
let name = '', email = '', vendorType = 'other', dealNote = '', clientNames = '';

if (raw.body && raw.body.email) {
  name = (raw.body.name || '').trim();
  email = raw.body.email;
  vendorType = (raw.body.vendorType || 'other').toLowerCase();
  dealNote = (raw.body.dealNote || '').trim();
  clientNames = (raw.body.clientNames || '').trim();
} else if (raw['Vendor name']) {
  name = raw['Vendor name'];
  email = raw['Vendor email'];
  vendorType = (raw['Vendor type'] || 'other').toLowerCase();
  dealNote = (raw['Property address'] || '').trim();
  clientNames = (raw['Client name(s)'] || '').trim();
}
if (!name || !email) { throw new Error('Missing vendor name or email'); }

const dealPhrase = dealNote ? ` on ${dealNote}` : '';
const clientLine = clientNames
  ? ` I know ${clientNames} had a memorable experience, and that's thanks to having a great team like you in my corner.`
  : '';
const subject = `Great working with you${dealNote ? ' on ' + dealNote : ''}`;

const html = [
  `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f2f1ee;padding:40px 16px;">`,
  `<tr><td align="center">`,
  `<table role="presentation" width="100%" style="max-width:540px;background:#ffffff;border:1px solid #e3e2de;border-radius:10px;font-family:'Aptos','Segoe UI',Calibri,Helvetica,Arial,sans-serif;">`,
  `<tr><td style="padding:36px 40px 28px;text-align:center;border-bottom:1px solid #eeece7;">`,
  `<div style="font-size:20px;font-weight:700;color:#1a3c34;">Hector Meza</div>`,
  `<div style="font-size:11px;color:#999;margin-top:6px;letter-spacing:1px;text-transform:uppercase;">Briggs Freeman Sotheby's International Realty</div>`,
  `</td></tr>`,
  `<tr><td style="padding:32px 40px 8px;font-size:15px;line-height:1.65;color:#222;">`,
  `<p style="margin:0 0 16px;">Dear ${name},</p>`,
  `<p style="margin:0 0 16px;">I wanted to take a moment to thank you for taking such great care of my clients${dealPhrase}.${clientLine}</p>`,
  `<p style="margin:0 0 24px;">If you have a moment, I would really appreciate a quick Google review. It takes about two minutes and helps other clients find me.</p>`,
  `</td></tr>`,
  `<tr><td style="padding:0 40px 28px;text-align:center;">`,
  `<a href="${link}" style="display:inline-block;background:#1a3c34;color:#ffffff;padding:13px 30px;border-radius:6px;text-decoration:none;font-weight:600;font-size:15px;">Leave a Google Review</a>`,
  `<p style="margin:16px 0 0;font-size:12px;color:#999;">Or copy this link</p>`,
  `<p style="margin:2px 0 0;font-size:12px;color:#1a3c34;word-break:break-all;">${link}</p>`,
  `</td></tr>`,
  `<tr><td style="padding:0 40px 36px;font-size:15px;line-height:1.65;color:#222;">`,
  `<p style="margin:0 0 16px;">If you haven't already, I'd love to return the favor, just send me your link and I'll leave you a review too.</p>`,
  `<p style="margin:0 0 20px;">Thank you again, and I look forward to working together on the next one.</p>`,
  `<p style="margin:0;">Sincerely,<br><strong>Hector Meza</strong><br>Briggs Freeman Sotheby's International Realty<br>(214) 686-5641 &middot; <a href="https://hectormeza.com" style="color:#1a3c34;text-decoration:none;">hectormeza.com</a></p>`,
  `</td></tr>`,
  `</table>`,
  `</td></tr>`,
  `</table>`
].join('');

return [{ json: {
  name, email, vendorType, dealNote, clientNames, sent_at: new Date().toISOString(),
  subject, html, raw: buildRaw(email, subject, html)
} }];

